                  <th class="text-center" style="width: 120px;">Áp dụng mẫu</th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="cam in filteredCameras" :key="cam.id" :class="getRowClass(cam.id)">
                  <td class="text-center">
