                  <td class="text-center bg-blue-1">
                    <q-checkbox v-model="matrix[cam.id].HumanTrait" color="primary" dense>
                      <q-tooltip v-if="matrix[cam.id].HumanTrait">Đang bật báo động khi có người vào!</q-tooltip>
