                  <td class="text-center bg-blue-1">
                    <q-checkbox v-model="matrix[cam.id].VideoMotion" color="primary" dense>
                      <q-tooltip v-if="matrix[cam.id].VideoMotion">Đang bật báo động khi có chuyển động!</q-tooltip>
