                        </q-item>
                        <q-item clickable v-close-popup @click="setCamPreset(cam.id, 'public')">
                          <q-item-section avatar><q-icon name="apartment" color="teal" size="xs" /></q-item-section>
                          <q-item-section>Công cộng (Chỉ Ẩu đả & Đột nhập)</q-item-section>
                        </q-item>
                        <q-item clickable v-close-popup @click="setCamPreset(cam.id, 'all')">
                          <q-item-section avatar><q-icon name="check_box" color="positive" size="xs" /></q-item-section>
