                        </q-item>
                        <q-item clickable v-close-popup @click="setCamPreset(cam.id, 'off')">
                          <q-item-section avatar><q-icon name="clear" color="negative" size="xs" /></q-item-section>
                          <q-item-section>Tắt hết cảnh báo</q-item-section>
                        </q-item>
                      </q-list>
                    </q-btn-dropdown>
                  </td>
                </tr>
              </tbody>
            </q-markup-table>
          </q-card-section>
        </q-card>
      </q-tab-panel>

      <!-- TAB 2: KẾT NỐI NVR & DỊCH VỤ -->
      <q-tab-panel name="nvr_connection" class="q-pa-none">
        <div class="row q-col-gutter-lg">
          <!-- NVR Connection Form -->
          <div class="col-12 col-lg-7">
            <q-card>
              <q-card-section class="row items-center justify-between">
                <div class="text-subtitle1 text-weight-bold text-primary">
                  <q-icon name="dns" class="q-mr-sm" />
                  Kết nối NVR
                </div>
                <q-badge :color="form.demo_mode ? 'amber-9' : 'positive'" :label="form.demo_mode ? 'Demo' : 'Trực tiếp'" />
              </q-card-section>
              <q-separator />

              <q-card-section>
                <q-form @submit.prevent="saveConfig" class="q-gutter-md">
                  <div class="row q-col-gutter-md">
                    <div class="col-12 col-md-8">
                      <q-input v-model="form.nvr_host" label="IP Đầu ghi *" outlined dense :rules="[v => !!v || 'Bắt buộc']">
                        <template #prepend><q-icon name="public" color="primary" /></template>
                      </q-input>
                    </div>
                    <div class="col-12 col-md-4">
                      <q-input v-model.number="form.nvr_port" type="number" label="Cổng HTTP *" outlined dense :rules="[v => !!v || 'Bắt buộc']">
