                <div class="row justify-between items-center">
                  <span class="text-grey-7">Dahua Listener:</span>
                  <q-badge :color="listenerStatus.listener?.is_running ? 'positive' : 'negative'" :label="listenerStatus.listener?.is_running ? 'Online' : 'Offline'" />
                </div>
                <div class="row justify-between items-center">
                  <span class="text-grey-7">Hàng đợi Worker:</span>
                  <span class="text-weight-bold text-primary">{{ listenerStatus.queue_size || 0 }} clip</span>
                </div>
                <div class="row justify-between items-center">
                  <span class="text-grey-7">Bộ nhớ NAS:</span>
                  <q-badge color="primary" :label="listenerStatus.nas_health?.backend || 'Local Storage'" />
                </div>
                <div class="q-pt-sm">
                  <q-btn outline dense color="primary" icon="refresh" label="Làm Mới" @click="fetchListener" class="full-width" />
                </div>
              </q-card-section>
            </q-card>

            <q-card>
              <q-card-section>
                <div class="text-subtitle1 text-weight-bold text-amber-9">
                  <q-icon name="cleaning_services" class="q-mr-sm" />
                  Dọn dẹp Storage
                </div>
              </q-card-section>
              <q-separator />
              <q-card-section>
                <div class="row items-center q-col-gutter-sm">
                  <div class="col-8">
                    <q-input v-model.number="retentionDays" type="number" label="Thời gian (ngày)" outlined dense />
                  </div>
                  <div class="col-4">
                    <q-btn unelevated color="amber-9" text-color="white" icon="delete_sweep" label="Dọn dẹp" class="full-width" @click="confirmPurge" :loading="purging" />
                  </div>
                </div>
                <div v-if="purgeResult" class="q-mt-sm text-caption text-positive">
                  Đã dọn dẹp: {{ purgeResult.deleted_events || 0 }} sự kiện, {{ purgeResult.deleted_clips || 0 }} file clip.
                </div>
              </q-card-section>
            </q-card>
          </div>
        </div>
      </q-tab-panel>
    </q-tab-panels>
  </q-page>
</template>

<script>
import { defineComponent, ref, reactive, computed, onMounted } from 'vue'
import { useQuasar } from 'quasar'

export default defineComponent({
  name: 'NvrConfig',
  setup () {
    const $q = useQuasar()
    const tab = ref('alert_matrix')
    const camSearch = ref('')

    const form = reactive({
      nvr_host: '',
      nvr_port: 80,
      rtsp_port: 554,
      nvr_user: '',
      nvr_password: '',
      use_https: false,
      demo_mode: false,
      active_channels: [],
      abnormal_event_codes: [],
      camera_names: {},
      camera_alert_rules: {}
    })

    const showPass = ref(false)
    const testing = ref(false)
    const saving = ref(false)
    const testResult = ref(null)

    const listenerStatus = reactive({})
    const retentionDays = ref(30)
    const purging = ref(false)
    const purgeResult = ref(null)

    // Per-camera matrix state
    const cameraNames = reactive({})
    const activeChannelsMap = reactive({})
    const matrix = reactive({})

    // Initialize 32 cameras
    for (let i = 1; i <= 32; i++) {
      const k = String(i)
      cameraNames[k] = `Kênh ${i < 10 ? '0' + i : i}`
      activeChannelsMap[k] = true
      matrix[k] = {
        Fight: true,
        Intrusion: true,
        CrossLine: true,
        AudioMutation: true,
        HumanTrait: false,
        VideoMotion: false
      }
    }

    const vipChannels = [7, 8, 17, 23, 24] // Kế toán, Phòng họp, Chủ tịch, Hiệu trưởng

    const isVipCamera = (chId) => vipChannels.includes(Number(chId))

    const getRowClass = (chId) => {
      if (isVipCamera(chId)) return 'bg-purple-1'
      return ''
    }

    const allCameras = computed(() => {
      const list = []
      for (let i = 1; i <= 32; i++) {
        list.push({ id: String(i), name: cameraNames[String(i)] || `Kênh ${i}` })
      }
      return list
    })

    const filteredCameras = computed(() => {
      if (!camSearch.value || !camSearch.value.trim()) return allCameras.value
      const q = camSearch.value.trim().toLowerCase()
      return allCameras.value.filter(c => {
        return c.id.includes(q) || (cameraNames[c.id] && cameraNames[c.id].toLowerCase().includes(q))
      })
    })

    const fetchConfig = async () => {
      try {
        const res = await fetch('/api/config/nvr')
        if (res.ok) {
          const data = await res.json()
          Object.assign(form, data)
          form.nvr_password = ''

          // Load camera names
          if (data.camera_names) {
            for (let i = 1; i <= 32; i++) {
              const k = String(i)
              if (data.camera_names[k]) {
                cameraNames[k] = data.camera_names[k]
              }
            }
          }

          // Load active channels
          const activeSet = new Set(data.active_channels || [])
          for (let i = 1; i <= 32; i++) {
            activeChannelsMap[String(i)] = activeSet.has(i)
          }

          // Load camera alert rules
          const rules = data.camera_alert_rules || {}
          for (let i = 1; i <= 32; i++) {
            const k = String(i)
            if (rules[k] && Array.isArray(rules[k])) {
              const ruleSet = new Set(rules[k])
              matrix[k] = {
                Fight: ruleSet.has('Fight'),
                Intrusion: ruleSet.has('Intrusion'),
                CrossLine: ruleSet.has('CrossLine'),
                AudioMutation: ruleSet.has('AudioMutation'),
                HumanTrait: ruleSet.has('HumanTrait'),
                VideoMotion: ruleSet.has('VideoMotion')
              }
            } else {
              // Default: VIP cameras get HumanTrait enabled
              matrix[k] = {
                Fight: true,
                Intrusion: true,
                CrossLine: true,
                AudioMutation: true,
                HumanTrait: isVipCamera(i),
                VideoMotion: isVipCamera(i)
              }
            }
          }
        }
      } catch (err) {
        $q.notify({ type: 'negative', message: 'Lỗi tải cấu hình NVR: ' + err.message })
      }
    }

    const setCamPreset = (chId, presetType) => {
      const k = String(chId)
      if (presetType === 'vip') {
        matrix[k] = { Fight: true, Intrusion: true, CrossLine: true, AudioMutation: true, HumanTrait: true, VideoMotion: true }
      } else if (presetType === 'public') {
        matrix[k] = { Fight: true, Intrusion: true, CrossLine: true, AudioMutation: true, HumanTrait: false, VideoMotion: false }
      } else if (presetType === 'all') {
        matrix[k] = { Fight: true, Intrusion: true, CrossLine: true, AudioMutation: true, HumanTrait: true, VideoMotion: true }
      } else if (presetType === 'off') {
        matrix[k] = { Fight: false, Intrusion: false, CrossLine: false, AudioMutation: false, HumanTrait: false, VideoMotion: false }
      }
    }

    const applyVipPreset = () => {
      vipChannels.forEach(ch => {
        setCamPreset(ch, 'vip')
      })
      $q.notify({ type: 'positive', message: 'Đã kích hoạt Mẫu VIP (Bật cảnh báo Người & Chuyển động) cho phòng Chủ tịch, Hiệu trưởng, Kế toán!' })
    }

    const applyPublicPreset = () => {
      for (let i = 1; i <= 32; i++) {
        if (!isVipCamera(i)) {
          setCamPreset(i, 'public')
        }
      }
      $q.notify({ type: 'positive', message: 'Đã áp dụng Mẫu Công cộng (Chỉ Ẩu đả & Đột nhập) cho các khu vực Sảnh & Hành lang!' })
    }

    const enableAllChannels = () => {
      for (let i = 1; i <= 32; i++) {
        activeChannelsMap[String(i)] = true
      }
      $q.notify({ type: 'positive', message: 'Đã kích hoạt toàn bộ 32 Camera!' })
    }

    const resetSafeDefaults = () => {
      for (let i = 1; i <= 32; i++) {
        activeChannelsMap[String(i)] = true
        if (isVipCamera(i)) {
          setCamPreset(i, 'vip')
        } else {
          setCamPreset(i, 'public')
        }
      }
      $q.notify({ type: 'info', message: 'Đã khôi phục ma trận cảnh báo theo tiêu chuẩn an ninh!' })
    }

    const fetchListener = async () => {
      try {
        const res = await fetch('/api/admin/listener-status')
        if (res.ok) {
          const data = await res.json()
          Object.assign(listenerStatus, data)
        }
      } catch (err) {
        console.error(err)
      }
    }

    const testConnection = async () => {
      testing.value = true
      testResult.value = null
      try {
        const payload = { ...form }
        if (!payload.nvr_password || !payload.nvr_password.trim()) {
          delete payload.nvr_password
        }
        const res = await fetch('/api/config/nvr/test', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        })
        const data = await res.json()
        testResult.value = data
        if (data.success) {
          $q.notify({ type: 'positive', message: data.message || 'Kết nối thành công!' })
        } else {
          $q.notify({ type: 'negative', message: data.message || 'Kết nối thất bại!' })
        }
      } catch (err) {
        testResult.value = { success: false, message: 'Lỗi mạng: ' + err.message }
        $q.notify({ type: 'negative', message: testResult.value.message })
      } finally {
        testing.value = false
      }
    }

    const saveConfig = async () => {
      saving.value = true
      try {
        // Build active_channels
        const activeList = []
        for (let i = 1; i <= 32; i++) {
          if (activeChannelsMap[String(i)]) {
            activeList.push(i)
          }
        }

        // Build camera_alert_rules
        const alertRules = {}
        for (let i = 1; i <= 32; i++) {
          const k = String(i)
          const codes = []
          const m = matrix[k] || {}
          if (m.Fight) codes.push('Fight')
          if (m.Intrusion) codes.push('Intrusion')
          if (m.CrossLine) codes.push('CrossLine')
          if (m.AudioMutation) codes.push('AudioMutation')
          if (m.HumanTrait) codes.push('HumanTrait')
          if (m.VideoMotion) codes.push('VideoMotion')
          alertRules[k] = codes
        }

        const payload = {
          ...form,
          active_channels: activeList,
          camera_names: { ...cameraNames },
          camera_alert_rules: alertRules
        }
        // Do not send empty password to prevent wiping the saved NVR password
        if (!payload.nvr_password || !payload.nvr_password.trim()) {
          delete payload.nvr_password
        }

        const res = await fetch('/api/config/nvr', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        })
        const data = await res.json()
        if (!res.ok) throw new Error(data.error || data.detail || 'Lỗi lưu NVR')
        $q.notify({ type: 'positive', message: data.message || 'Đã lưu cấu hình NVR & Ma trận cảnh báo thành công!' })
        form.nvr_password = ''
        await fetchConfig()
        await fetchListener()
      } catch (err) {
        $q.notify({ type: 'negative', message: err.message })
      } finally {
        saving.value = false
      }
    }

    const confirmPurge = () => {
      $q.dialog({
        title: 'Xác nhận Dọn rác Lưu trữ',
        message: `Bạn có chắc muốn xóa vĩnh viễn các video cũ hơn ${retentionDays.value} ngày không?`,
        cancel: true,
        persistent: true,
        ok: { label: 'Dọn rác ngay', color: 'amber-9' }
      }).onOk(async () => {
        purging.value = true
        try {
          const res = await fetch(`/api/admin/storage/purge-retention?days=${retentionDays.value}`, { method: 'POST' })
          const data = await res.json()
          purgeResult.value = data
          $q.notify({ type: 'positive', message: `Đã dọn dẹp ${data.deleted_events || 0} sự kiện!` })
        } catch (err) {
          $q.notify({ type: 'negative', message: 'Lỗi dọn rác: ' + err.message })
        } finally {
          purging.value = false
        }
      })
    }

    onMounted(() => {
      fetchConfig()
      fetchListener()
    })

    return {
      tab,
      camSearch,
      form,
      cameraNames,
      activeChannelsMap,
      matrix,
      filteredCameras,
      showPass,
      testing,
      saving,
      testResult,
      listenerStatus,
      retentionDays,
      purging,
      purgeResult,
      isVipCamera,
      getRowClass,
      fetchConfig,
      fetchListener,
      testConnection,
      saveConfig,
      confirmPurge,
      setCamPreset,
      applyVipPreset,
      applyPublicPreset,
      enableAllChannels,
      resetSafeDefaults
    }
  }
})
</script>

